#!/usr/bin/env node
// Sync the canonical specialist subagents in .claude/agents/*.md to:
//   - Codex:       .codex/agents/<name>.toml
//   - Antigravity: .agents/plugins/puddle-island/agents/<name>.md
//
// Keeping one hand-edited source prevents prompt drift across tools.
//
//   node scripts/sync-agents.mjs          # write generated files
//   node scripts/sync-agents.mjs --check  # exit 1 if any generated file is missing, stale, or extra
import { existsSync, mkdirSync, readdirSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

export const repoRoot = resolve(dirname(new URL(import.meta.url).pathname), '..');

const TOOL_MAP = {
  Read: ['read_file'],
  Grep: ['read_file'],
  Glob: ['read_file'],
  Edit: ['edit_file'],
  MultiEdit: ['edit_file'],
  Write: ['write_file'],
  Bash: ['run_command', 'manage_task'],
  WebSearch: ['search_web'],
  WebFetch: ['search_web'],
};

/** Parse a Claude Code agent Markdown file (`---` frontmatter + body). */
export function parseClaudeAgent(text, fileName = '<agent>') {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/.exec(text);
  if (!match) throw new Error(`Missing YAML frontmatter in ${fileName}`);
  const meta = {};
  for (const line of match[1].split(/\r?\n/)) {
    if (!line.trim()) continue;
    const colon = line.indexOf(':');
    if (colon < 0) throw new Error(`Invalid frontmatter line in ${fileName}: ${line}`);
    const key = line.slice(0, colon).trim();
    const val = line.slice(colon + 1).trim();
    meta[key] = val;
  }
  if (!meta.name || !meta.description) {
    throw new Error(`Agent ${fileName} must declare name and description`);
  }
  const tools = meta.tools
    ? meta.tools
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean)
    : [];
  const body = match[2].trim();
  return { name: meta.name, description: meta.description, tools, body };
}

/** Map Claude tool names to Antigravity native tool names. */
export function mapAntigravityTools(claudeTools) {
  if (!claudeTools || claudeTools.length === 0) {
    return ['read_file', 'edit_file', 'write_file', 'run_command', 'manage_task', 'search_web'];
  }
  const out = [];
  for (const tool of claudeTools) {
    for (const mapped of TOOL_MAP[tool] ?? []) {
      if (!out.includes(mapped)) out.push(mapped);
    }
  }
  return out;
}

function tomlMultiline(str) {
  return str.replace(/\\/g, '\\\\').replace(/"""/g, '""\\"');
}

export function renderCodexAgent(agent, sourceRel) {
  return [
    `# Generated by node scripts/sync-agents.mjs from ${sourceRel}. Do not edit by hand.`,
    `name = ${JSON.stringify(agent.name)}`,
    `description = ${JSON.stringify(agent.description)}`,
    'developer_instructions = """',
    tomlMultiline(agent.body),
    '"""',
    '',
  ].join('\n');
}

export function renderAntigravityAgent(agent, sourceRel) {
  const tools = mapAntigravityTools(agent.tools);
  // Adjust depth-2 links from .claude/agents/ (../../docs/) to depth-4 (.agents/plugins/puddle-island/agents/).
  const body = agent.body.replace(/\]\(\.\.\/\.\.\/docs\//g, '](../../../../docs/');
  return [
    '---',
    `name: ${agent.name}`,
    `description: ${JSON.stringify(agent.description)}`,
    'subagent: true',
    'mainAgent: false',
    `tools: [${tools.join(', ')}]`,
    '---',
    `<!-- Generated by node scripts/sync-agents.mjs from ${sourceRel}. Do not edit by hand. -->`,
    body,
    '',
  ].join('\n');
}

/** Return a Map of repo-relative generated path -> expected UTF-8 content. */
export function expectedAgentOutputs(rootDir = repoRoot) {
  const sourceDir = join(rootDir, '.claude', 'agents');
  const files = readdirSync(sourceDir)
    .filter((f) => f.endsWith('.md'))
    .sort();
  const outputs = new Map();
  for (const file of files) {
    const sourceRel = `.claude/agents/${file}`;
    const raw = readFileSync(join(sourceDir, file), 'utf8');
    const agent = parseClaudeAgent(raw, sourceRel);
    outputs.set(`.codex/agents/${agent.name}.toml`, renderCodexAgent(agent, sourceRel));
    outputs.set(
      `.agents/plugins/puddle-island/agents/${agent.name}.md`,
      renderAntigravityAgent(agent, sourceRel),
    );
  }
  return outputs;
}

/** Find missing, stale, or stray generated agent files. */
export function findAgentDrift(rootDir = repoRoot) {
  const expected = expectedAgentOutputs(rootDir);
  const issues = [];
  for (const [rel, want] of expected) {
    const abs = join(rootDir, rel);
    if (!existsSync(abs)) {
      issues.push(`missing: ${rel}`);
      continue;
    }
    const have = readFileSync(abs, 'utf8');
    if (have !== want) issues.push(`stale: ${rel}`);
  }
  const managedDirs = [
    { rel: '.codex/agents', ext: '.toml' },
    { rel: '.agents/plugins/puddle-island/agents', ext: '.md' },
  ];
  for (const { rel, ext } of managedDirs) {
    const abs = join(rootDir, rel);
    if (!existsSync(abs)) continue;
    for (const file of readdirSync(abs).sort()) {
      if (!file.endsWith(ext)) continue;
      const fullRel = `${rel}/${file}`;
      if (!expected.has(fullRel)) issues.push(`extra: ${fullRel}`);
    }
  }
  return issues;
}

export function syncAgents(rootDir = repoRoot) {
  const expected = expectedAgentOutputs(rootDir);
  for (const [rel, content] of expected) {
    const abs = join(rootDir, rel);
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content, 'utf8');
  }
  for (const issue of findAgentDrift(rootDir)) {
    if (issue.startsWith('extra: ')) {
      unlinkSync(join(rootDir, issue.slice('extra: '.length)));
    }
  }
  return [...expected.keys()];
}

const isMain = Boolean(process.argv[1]) && import.meta.url === pathToFileURL(resolve(process.argv[1])).href;
if (isMain) {
  const check = process.argv.includes('--check');
  if (check) {
    const issues = findAgentDrift(repoRoot);
    if (issues.length > 0) {
      console.error('Generated subagent configs are out of sync. Run `node scripts/sync-agents.mjs`:');
      for (const issue of issues) console.error(`  ${issue}`);
      process.exit(1);
    }
    console.log('subagents in sync');
  } else {
    const written = syncAgents(repoRoot);
    console.log(`synced ${written.length} subagent files`);
  }
}
